from math import isqrt

def words_in_sentence(sentence):
    """
    Returns a string containing words from the input sentence
    whose lengths are prime numbers, preserving original order.
    """
    def is_prime(n):
        if n < 2:
            return False
        if n in (2, 3):
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        limit = isqrt(n)
        f = 5
        while f <= limit:
            if n % f == 0 or n % (f + 2) == 0:
                return False
            f += 6
        return True

    words = sentence.split(" ")
    filtered = [w for w in words if is_prime(len(w))]
    return " ".join(filtered)
